using Microsoft.EntityFrameworkCore;using ZosyalMedya.Modules.Communities.Application.Communities;using ZosyalMedya.Modules.Communities.Domain.Communities;using ZosyalMedya.Modules.Communities.Infrastructure.Persistence;using Xunit;
namespace ZosyalMedya.Tests.Integration.Persistence;public sealed class CommunityRepositoryTests{[Fact]public async Task MembershipRulesPinsAndAuditPersist(){if(!InfrastructureTestGate.IsEnabled)return;var db=new CommunitiesDbContext(new DbContextOptionsBuilder<CommunitiesDbContext>().UseNpgsql("Host=localhost;Port=55432;Database=zosyalmedya;Username=zosyalmedya;Password=local_only_change_me").Options);await db.Database.MigrateAsync();var repository=new PostgreSqlCommunityRepository(db);var now=new DateTimeOffset(2026,7,12,18,0,0,TimeSpan.Zero);var owner=new CommunityActorId(Guid.NewGuid());var member=new CommunityActorId(Guid.NewGuid());var item=Community.Create(CommunityId.New(),owner,$"contract-{Guid.NewGuid():N}","Sözleşme Topluluğu","Açıklama",CommunityVisibility.Public,now);await repository.CreateAsync(item);var version=item.Version;item.RequestMembership(member,now);item.SetRules(owner,["Birinci kural"],now);var content=Guid.NewGuid();item.Pin(owner,content,true,now);Assert.True(await repository.UpdateAsync(x=>x.Id==item.Id,item,version));var loaded=await repository.SelectAsync(x=>x.Id==item.Id);Assert.NotNull(loaded);Assert.True(loaded.HasActiveMember(member));Assert.Single(loaded.Rules);Assert.Contains(content,loaded.PinnedContentIds);Assert.True(loaded.AuditHistory.Count>=4);Assert.Equal(1,await repository.DeleteByFilterAsync(x=>x.Id==item.Id));}
[Fact]public async Task HiddenDetailIsVisibleOnlyToActiveMemberAndReturnsNoMemberIdentities(){if(!InfrastructureTestGate.IsEnabled)return;var db=new CommunitiesDbContext(new DbContextOptionsBuilder<CommunitiesDbContext>().UseNpgsql("Host=localhost;Port=55432;Database=zosyalmedya;Username=zosyalmedya;Password=local_only_change_me").Options);await db.Database.MigrateAsync();var repository=new PostgreSqlCommunityRepository(db);var now=new DateTimeOffset(2026,8,13,8,0,0,TimeSpan.Zero);var owner=new CommunityActorId(Guid.NewGuid());var slug=$"hidden-{Guid.NewGuid():N}";var item=Community.Create(CommunityId.New(),owner,slug,"Gizli Topluluk","Açıklama",CommunityVisibility.Hidden,now);await repository.CreateAsync(item);var handler=new GetCommunityHandler(repository);Assert.False((await handler.HandleAsync(slug,Guid.NewGuid(),default)).IsSuccess);var view=await handler.HandleAsync(slug,owner.Value,default);Assert.True(view.IsSuccess);Assert.Equal(1,view.Value!.ActiveMemberCount);Assert.Equal("Owner",view.Value.ViewerRole);Assert.Equal(1,await repository.DeleteByFilterAsync(x=>x.Id==item.Id));}
[Fact]public async Task RuleReplacementDeletesRemovedOwnedRows(){if(!InfrastructureTestGate.IsEnabled)return;var db=new CommunitiesDbContext(new DbContextOptionsBuilder<CommunitiesDbContext>().UseNpgsql("Host=localhost;Port=55432;Database=zosyalmedya;Username=zosyalmedya;Password=local_only_change_me").Options);await db.Database.MigrateAsync();var repository=new PostgreSqlCommunityRepository(db);var now=new DateTimeOffset(2026,8,14,8,0,0,TimeSpan.Zero);var owner=new CommunityActorId(Guid.NewGuid());var item=Community.Create(CommunityId.New(),owner,$"rules-{Guid.NewGuid():N}","Kural Topluluğu","Açıklama",CommunityVisibility.Public,now);item.SetRules(owner,["Birinci kural","İkinci kural"],now);await repository.CreateAsync(item);var loaded=await repository.SelectAsync(x=>x.Id==item.Id);var version=loaded!.Version;loaded.SetRules(owner,["Tek kural"],now.AddMinutes(1));Assert.True(await repository.UpdateAsync(x=>x.Id==loaded.Id,loaded,version));loaded=await repository.SelectAsync(x=>x.Id==item.Id);Assert.Equal(["Tek kural"],loaded!.Rules.Select(x=>x.Text));version=loaded.Version;loaded.SetRules(owner,[],now.AddMinutes(2));Assert.True(await repository.UpdateAsync(x=>x.Id==loaded.Id,loaded,version));loaded=await repository.SelectAsync(x=>x.Id==item.Id);Assert.Empty(loaded!.Rules);Assert.Equal(1,await repository.DeleteByFilterAsync(x=>x.Id==item.Id));}}
